function prng(seed){var a=(seed>>>0)||1;return function(){a|=0;a=(a+0x6D2B79F5)|0;var t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;};}
function demoRun(seed){var R=prng(seed*699999+79);var items=['solid-state cooling','photonic interconnect','dna storage','room-temp qubit','self-healing alloy'];var stages=['research','simulation','prototype','benchmark'];var rep=items.map(function(it){var st=stages.map(function(s){return{stage:s,gate:R()<0.75?'pass':'fail'};});return{item:it,stages:st};});var passes=0,fails=0;rep.forEach(function(r){r.stages.forEach(function(s){if(s.gate==='pass')passes++;else fails++;});});return{research_items:items.length,stage_results:rep,total_gates_passed:passes,total_gates_failed:fails};}
var SEED = 98001;
console.log(JSON.stringify(demoRun(SEED), null, 1));

